import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Remove duplicate events (same seq) - keep first occurrence
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort by seq to respect log order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Apply replay guard - filter events where seq <= last_seq for existing orders
    # Create a mapping of order_id to last_seq from target_state
    order_last_seq = dict(zip(target_state["order_id"], target_state["last_seq"]))

    def should_apply_event(row):
        order_id = row["order_id"]
        seq = row["seq"]
        # If order exists in target_state and seq <= last_seq, skip
        if order_id in order_last_seq and seq <= order_last_seq[order_id]:
            return False
        return True

    cdc_events = cdc_events[cdc_events.apply(should_apply_event, axis=1)].reset_index(drop=True)

    # Step 4: Apply events in seq order
    # Initialize new_state as a copy of target_state
    new_state = target_state.copy()
    new_state_dict = {}
    for _, row in target_state.iterrows():
        new_state_dict[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders had rows at some point (for tombstone detection)
    orders_ever_existed = set(target_state["order_id"].values)

    # Track last operation per order for tombstone logic
    last_op_per_order = {}
    last_seq_per_order = {}

    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        orders_ever_existed.add(order_id)
        last_op_per_order[order_id] = op
        last_seq_per_order[order_id] = seq

        if op in ["I", "U"]:
            if order_id not in new_state_dict:
                # Create new row
                new_state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                # Update existing row
                new_state_dict[order_id]["status"] = status
                # For 'U' with NULL amount, keep existing amount; otherwise use new amount
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    new_state_dict[order_id]["amount"] = amount
                new_state_dict[order_id]["last_seq"] = seq
        elif op == "D":
            # Delete row if it exists
            if order_id in new_state_dict:
                del new_state_dict[order_id]

    # Step 5: Build new_state DataFrame
    if new_state_dict:
        new_state_rows = []
        for order_id, state in new_state_dict.items():
            new_state_rows.append({
                "order_id": order_id,
                "status": state["status"],
                "amount": state["amount"],
                "last_seq": state["last_seq"]
            })
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure proper types in new_state
    if len(new_state) > 0:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
    else:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # Step 6: Build tombstones - orders whose last applied event was 'D'
    tombstone_rows = []
    for order_id in orders_ever_existed:
        if order_id in last_op_per_order and last_op_per_order[order_id] == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": last_seq_per_order[order_id]
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
